<details class="inline-correction"><summary>Edit</summary><form class="data-edit" method="post" action="{{ $action }}">@csrf<input type="hidden" name="expected" value="{{ $expected }}"><input type="hidden" name="field" value="{{ $field }}"><label>Suggested value<input name="value" maxlength="1000" value="{{ $value }}"></label><label>Format<select name="value_type"><option value="number" @selected(is_int($value)||is_float($value))>Number</option><option value="text" @selected(is_string($value))>Text / code</option><option value="missing" @selected($value===null)>Unavailable</option></select></label><label>Reason<textarea name="reason" required minlength="10" maxlength="2000"></textarea></label><label>Supporting source URL<input name="reference_url" type="url" maxlength="2000"></label><button class="data-button primary">Submit for admin review</button></form></details>
